<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class AuthController extends Controller { public function showLogin(){return view('auth.login');} public function login(Request $request){$data=$request->validate(['identity'=>['required','string'],'password'=>['required','string'],'role'=>['required',Rule::in(['student','parent','teacher','admin'])]]);$user=User::query()->where('portal_id',$data['identity'])->orWhere('email',$data['identity'])->first();if(!$user||$user->role!==$data['role']||!Hash::check($data['password'],$user->password)){return back()->withErrors(['identity'=>'The supplied credentials or role are incorrect.'])->onlyInput('identity');}Auth::login($user,$request->boolean('remember'));$request->session()->regenerate();return redirect()->route('portal.dashboard',$user->role);} public function logout(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');} }
